import * as React from "react";

let _useEffect;
let _useLocation;
let _useNavigationType;
let _createRoutesFromChildren;
let _matchRoutes;

export const reactRouterV6BrowserTracingIntegration = (options) => {
  const { useEffect, useLocation, useNavigationType, createRoutesFromChildren, matchRoutes } =
    options;
  return {
    name: "BrowserTracing",
    setup() {
      _useEffect = useEffect;
      _useLocation = useLocation;
      _useNavigationType = useNavigationType;
      _createRoutesFromChildren = createRoutesFromChildren;
      _matchRoutes = matchRoutes;
    },
  };
};

export const init = (options) => {
  for (const integration of options.integrations ?? []) integration.setup();
};

export const withSentryReactRouterV6Routing = (Routes) => {
  if (!_useEffect || !_useLocation || !_useNavigationType || !_createRoutesFromChildren || !_matchRoutes) {
    return Routes;
  }
  const SentryRoutes = (props) => {
    const isMountRenderPass = React.useRef(true);
    const location = _useLocation();
    const navigationType = _useNavigationType();
    _useEffect(() => {
      _createRoutesFromChildren(props.children);
      isMountRenderPass.current = false;
    }, [location, navigationType]);
    return React.createElement(Routes, { ...props });
  };
  return SentryRoutes;
};
